s <- readLines("figure.svg")
idx <- grep("<rect", s)
getnum <- function(line, key){
  m <- regmatches(line, regexpr(paste0(key,"='[-0-9.]+'"), line))
  if(length(m)==0) return(NA_real_) else as.numeric(sub(".*='([-0-9.]+)'","\\1",m))
}
res <- lapply(idx, function(i){
  line <- s[i]
  x <- getnum(line,"x"); y <- getnum(line,"y"); w <- getnum(line,"width"); h <- getnum(line,"height")
  data.frame(i=i,x=x,y=y,w=w,h=h,cx=x+w/2,cy=y+h/2, style=regmatches(line, regexpr("style=[^>]*", line)))
})
d <- do.call(rbind,res)
d <- d[!is.na(d$cx),]
print(nrow(d))
print(head(d[order((d$cx-386)^2 + (d$cy-288.02)^2),],8))
saveRDS(d,"rects.rds")

